item.command:
/bin/bash -lc "python3 - <<'PY'
import subprocess,json
r=subprocess.run(['python3','/workspace/tools.py','resolve','run://r-001'],capture_output=True,text=True,check=True)
x=json.loads(r.stdout)
print('TOP_KEYS',list(x))
for k,v in x.items():
 if k"'!='"'context' and k"'!='"'retrieval': print(k,json.dumps(v,indent=2))
print('CONTEXT_KEYS',list(x.get('context',{})))
for k,v in x.get('context',{}).items():
 if k not in ['history','knowledge','retrieval']: print(k,json.dumps(v,indent=2))
PY"

