/bin/bash -lc "python3 - <<'PY'
import ast,hashlib,importlib.util,json,pathlib,subprocess
p=pathlib.Path('/workspace'); proposal=json.loads((p/'proposal.json').read_text());runtime=json.loads(subprocess.run(['python3',str(p/'tools.py'),'resolve','run://r-001'],capture_output=True,text=True,check=True).stdout)
def validate(value,schema,path='"'$'"'):
 typ=schema.get('type')
 if typ=='object':
  assert isinstance(value,dict),(path,'object')
  assert set(schema.get('required',[]))<=set(value),(path,'required')
  if schema.get('additionalProperties') is False: assert set(value)<=set(schema.get('properties',{})),(path,'unknown keys')
  for k,v in value.items():
   if k in schema.get('properties',{}):validate(v,schema['properties'][k],path+'.'+k)
 elif typ=='array':
  assert isinstance(value,list) and len(value)>=schema.get('minItems',0),(path,'array')
  for i,v in enumerate(value):validate(v,schema.get('items',{}),path+'['+str(i)+']')
 elif typ=='string':assert isinstance(value,str) and len(value)>=schema.get('minLength',0),(path,'string')
 if 'const' in schema:assert value==schema['const'],(path,'const')
 if 'enum' in schema:assert value in schema['enum'],(path,'enum')
validate(proposal['study'],runtime['study_schema'])
assert proposal['study']['protocol_ref']==runtime['required_study_protocol_ref']
allowed=set(runtime['context']['allowed_observation_ids'])
assert set(proposal['study']['evidence_refs'])<=allowed
assert proposal['parent_trial'] in allowed
assert 1<=len(proposal['variants'])<=4 and any(v['role']=='candidate' for v in proposal['variants'])
assert len({v['name'] for v in proposal['variants']})==len(proposal['variants'])
configs={};bodies=[]
for name in ['history_r0029_crossed_full.py','history_r0029_crossed_half.py']+[v['file'] for v in proposal['variants']]:
 source=(p/name).read_text();compile(source,name,'exec');tree=ast.parse(source)
 for n in ast.walk(tree):
  if isinstance(n,ast.Import):assert all(x.name.split('.')[0] in ['torch'] for x in n.names)
  if isinstance(n,ast.ImportFrom):assert n.module=='torch'
 assignment=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 configs[name]=ast.literal_eval(assignment.value)
 tree.body.remove(assignment);bodies.append(ast.dump(tree,include_attributes=False))
 assert all(not(isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id in ['open','eval','exec','__import__']) for n in ast.walk(tree))
for v in proposal['variants']:
 assert pathlib.Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 assert configs[v['file']]==v['config']
 assert v['config']['row_intervention']=='none'
 assert hashlib.sha256((p/v['file']).read_bytes()).hexdigest() in v['note']
assert len(set(bodies))==1,'four-cell source mismatch'
assert {(v['product_pairing'],v['normalization_gradient']) for v in configs.values()}=={(a,b) for a in ['aligned','crossed'] for b in ['full','scale_half_tangent']}
for file,expected in [('baseline_reference.py','ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'),('history_r0029_crossed_full.py','7e501a53e4c41e09e3eaadde0fdc243faa356f309d83b343797b836f0df31180'),('history_r0029_crossed_half.py','73967e40f840a20a879902edb568b1b0ea97761a09b6d7c8a6dbd70bc58ce3e3')]:assert hashlib.sha256((p/file).read_bytes()).hexdigest()==expected
retrieved_industry={x['id'] for x in runtime['retrieved_evidence']['cards'] if x.get('knowledge_type')=='industry'}
assert retrieved_industry<={a['knowledge_id'] for a in proposal['knowledge_assessments']}
assert all(set(a['variant_names'])<={v['name'] for v in proposal['variants']} for a in proposal['knowledge_assessments'])
print('PASS study schema, protocol, local evidence IDs, two variant declarations, knowledge coverage, numeric imports, model syntax, source hashes and complete four-cell AST identity except CONFIG.')
print('Common non-CONFIG AST SHA256',hashlib.sha256(bodies[0].encode()).hexdigest())
print('Torch available:',importlib.util.find_spec('torch') is not None,'; no model execution or training attempted.')
print('Budget slack under explicit planning allowances:',proposal['resource_accounting']['slack_seconds'],'seconds; actual assessment tariff remains unverified.')
PY"

